package com.openggf.game.soniccd;
import org.junit.jupiter.api.Test;import java.util.*;import static org.junit.jupiter.api.Assertions.*;
import com.openggf.game.soniccd.objects.*;import static com.openggf.game.soniccd.objects.CdObjectState.ByteField.*;import static com.openggf.game.soniccd.objects.CdObjectState.WordField.*;
/** Tests FIRST, Java UNRUN. Constructed complete Core/Ports controls use original media and
 * the real cached Flower producer; never World/clear authority or trace hydration. */
class TestCdR31FlowerPositions {
 @Test void ordinaryConstructedDataHasNoImplicitKnownZeroBytes(){var p=CdFlowerPositions.unknown();assertEquals(0,p.knownBytes());assertFalse(p.clearedByOriginal());assertThrows(CdFlowerPositions.Unavailable.class,()->p.word(0));assertThrows(CdFlowerPositions.Unavailable.class,()->p.word(0x2FE));assertThrows(CdFlowerPositions.Unavailable.class,()->p.word(0x300));assertTrue(Arrays.stream(CdFlowerPositions.class.getDeclaredConstructors()).allMatch(c->java.lang.reflect.Modifier.isPrivate(c.getModifiers())));}
 @Test void originalPresentStoresCoverAllSixtyFourIndicesWithoutKnowingOtherBytes()throws Exception{
  for(int index=0;index<64;index++)try(var h=new TestSonicCdR31aObjectPass.Harness()){
   level(h,index<<8);seed(h);h.walk();var p=h.cut.core().flowerPositions();int x=0x100+index*4;assertEquals(4,p.knownBytes());assertEquals(96,p.word(x));assertEquals(h.placement.pool().state(32).centreY(),p.word(x+2));assertFalse(p.clearedByOriginal());assertThrows(CdFlowerPositions.Unavailable.class,()->p.word(0));assertEquals(4,h.placement.pool().state(32).routine());h.finish();}}
 @Test void originalXStoreIsRetainedBeforeFirstYPortFailure()throws Exception{fault(false);}
 @Test void originalBothWordsAreRetainedAfterYPortError()throws Exception{fault(true);}
 @Test void originalCountWrapStillUsesOldLowSixBitsAndRetainsAllOtherPeriods()throws Exception{try(var h=new TestSonicCdR31aObjectPass.Harness()){level(h,0xA5FF3C);seed(h);h.walk();assertEquals(0xA5003C,h.cut.core().level().flowerCount());assertEquals(96,h.cut.core().flowerPositions().word(0x1FC));h.finish();}}
 @Test void representedWordAliasesPreserveIndependentNativeCountAndFadeBytes(){var l=new CdLevelGlobals(1,2,3,4,5,0xAABBCC,0xDD,6,7);var x=CdFlowerPositions.aliasWord(l,0x300,0x1234);assertEquals(0x1234CC,x.flowerCount());assertEquals(0xDD,x.fadeEnableDisplay());var y=CdFlowerPositions.aliasWord(x,0x302,0x5678);assertEquals(0x123456,y.flowerCount());assertEquals(0x78,y.fadeEnableDisplay());assertThrows(CdFlowerPositions.Unavailable.class,()->CdFlowerPositions.aliasWord(l,0x304,1));assertThrows(IllegalArgumentException.class,()->CdFlowerPositions.aliasWord(l,0x300,0x10000));}
 @Test void literalSourceIndexBoundariesDoNotNormalizeRawPeriods(){assertEquals(0xFC,(63&63)*4+((0&127)<<8));assertEquals(0x1FC,(255&63)*4+((0x81&127)<<8));assertEquals(0x2FE,((63&63)*4+((2&127)<<8)+2)&65535);assertEquals(0x300,((64&63)*4+((3&127)<<8))&65535);assertEquals(0x304,((1&63)*4+((3&127)<<8))&65535);assertEquals(0x7FFE,((255&63)*4+((255&127)<<8)+2)&65535);}
 @Test void rejectedCloneAndRepeatCannotReplaceAnOriginalPositionOccurrence()throws Exception{try(var h=new TestSonicCdR31aObjectPass.Harness()){seed(h);var b=(CdFlower)field(h.pass,"flower");var port=(CdFlower.SavedPort)field(b,"savedPort");set(b,"savedPort",(CdFlower.SavedPort)c->{if(c.site()==CdFlower.SavedSite.POSITION_X){var clone=new CdFlower.SavedCall(c.ordinal(),c.site(),c.cut(),c.source(),c.offset(),c.value());assertThrows(IllegalStateException.class,()->port.access(clone));}int value=port.access(c);if(c.site()==CdFlower.SavedSite.POSITION_X)assertThrows(IllegalStateException.class,()->port.access(c));return value;});h.walk();assertFalse(h.frame.closed());assertEquals(96,h.cut.core().flowerPositions().word(0x100));h.finish();}}
 private static void fault(boolean after)throws Exception{try(var h=new TestSonicCdR31aObjectPass.Harness()){seed(h);var before=h.placement.capture();var b=(CdFlower)field(h.pass,"flower");var port=(CdFlower.SavedPort)field(b,"savedPort");var error=new AssertionError("original Y position owner");set(b,"savedPort",(CdFlower.SavedPort)c->{if(c.site()==CdFlower.SavedSite.POSITION_Y){if(after)port.access(c);throw error;}return port.access(c);});assertSame(error,assertThrows(AssertionError.class,h::walk));assertEquals(96,h.cut.core().flowerPositions().word(0x100));if(after)assertEquals(h.placement.pool().state(32).centreY(),h.cut.core().flowerPositions().word(0x102));else assertThrows(CdFlowerPositions.Unavailable.class,()->h.cut.core().flowerPositions().word(0x102));assertEquals(0x100,h.cut.core().level().flowerCount());assertEquals(2,h.placement.pool().state(32).routine());assertArrayEquals(before.savedFlags().copy(),h.placement.capture().savedFlags().copy());assertNull(field(h.pass,"flowerEffect"));}}
 static void seed(TestSonicCdR31aObjectPass.Harness h){TestSonicCdR31aFlowerPass.seed(h,32,2,0,96,1024);}
 static void level(TestSonicCdR31aObjectPass.Harness h,int count){var c=h.cut;var l=c.core().level();var n=new CdLevelGlobals(l.levelRestart(),l.updateHudTime(),l.checkpoint(),l.spawnMode(),l.plcLoadFlags(),count,l.fadeEnableDisplay(),l.powerup(),l.timeOver());h.cut=new SonicCdR31aObjectPass.Cut(c.core().level(n),c.ring(),c.currentTerrain(),c.contact(),c.world(),c.noBumperByte(),c.cameraXWord(),c.cameraYWord(),c.scrollLockWord(),c.layerByte(),c.cpuSat(),c.completedCpu(),c.sounds(),c.amyCapturedByte());}
 static Object field(Object o,String n)throws Exception{var f=o.getClass().getDeclaredField(n);f.setAccessible(true);return f.get(o);}static void set(Object o,String n,Object v)throws Exception{var f=o.getClass().getDeclaredField(n);f.setAccessible(true);f.set(o,v);}
}
